@push('scripts')<script>(function(){var pageSize=10;function render(modal,page){var rows=Array.prototype.slice.call(modal.querySelectorAll('.ap-detail-row')),total=rows.length,last=Math.max(1,Math.ceil(total/pageSize));page=Math.max(1,Math.min(page,last));rows.forEach(function(row,index){row.style.display=index>=(page-1)*pageSize&&index<page*pageSize?'':'none';});var from=total?(page-1)*pageSize+1:0,to=Math.min(page*pageSize,total),summary=modal.querySelector('.ap-detail-summary'),pages=modal.querySelector('.ap-detail-pages');summary.textContent='显示第 '+from+'-'+to+' 条，共 '+total+' 条';var html='<button type="button" class="btn btn-default btn-xs ap-page-btn" data-page="'+(page-1)+'" '+(page<=1?'disabled':'')+'><i class="fa fa-angle-left"></i></button>';var start=Math.max(1,page-2),end=Math.min(last,start+4);start=Math.max(1,end-4);for(var i=start;i<=end;i++)html+='<button type="button" class="btn btn-default btn-xs ap-page-btn '+(i===page?'active':'')+'" data-page="'+i+'">'+i+'</button>';html+='<button type="button" class="btn btn-default btn-xs ap-page-btn" data-page="'+(page+1)+'" '+(page>=last?'disabled':'')+'><i class="fa fa-angle-right"></i></button>';pages.innerHTML=html;modal.setAttribute('data-current-page',page);}$(document).on('show.bs.modal','.ap-detail-modal',function(){render(this,1);});document.addEventListener('click',function(event){var button=event.target.closest('.ap-page-btn');if(!button||button.disabled)return;var modal=button.closest('.ap-detail-modal');render(modal,parseInt(button.getAttribute('data-page'),10)||1);});})();</script>@endpush
